(function () {
  "use strict";
  const V = window.VTB;
  const $ = (s, r = document) => r.querySelector(s);
  const $$ = (s, r = document) => Array.from(r.querySelectorAll(s));
  const AG = Object.fromEntries(V.AGENTS.map((a) => [a.id, a]));
  const ZH = /^zh/i.test(document.documentElement.lang);
  // UI strings generated by this script; static page text lives in index.html / index.zh.html.
  const I = ZH ? {
    data: "数据", trainer: "训练器", harness: "推理框架",
    tcHarness: "推理框架", tcVal: "验证集", tcTest: "隐藏测试集", tcSettings: "评测设置",
    agentCol: "研究智能体", avg: "平均", hours: "时长 (h)",
    refInit: "初始 ", refInst: "Instruct ",
    tcCap: (name, who, s, d, inst, spread) => `<b>${name}</b> · 领先者：<b>${who}</b>，得分 ${s}%（比初始系统高 ${d} 分）。人工开发的 Instruct 模型得分 ${inst}%；各研究智能体之间相差 ${spread} 分。`,
    fiveAvg: "五任务平均",
    vtHead: ["任务", "验证集领先者", "", "隐藏测试集领先者"],
    abInit: "初始", abCap: "Kimi-K3 的隐藏测试集得分（%）。Kimi-K3 在 SWE 的 D/T/H 运行中没有修改推理框架。",
    sparkTitle: "每个决策的验证结果", sparkHollow: " · 空心点 = 子集验证",
    meta: (task, fw, fig) => `${task} · ${fw} · 论文${fig.replace("Figure ", "图 ")}`,
    hidden: (x) => `隐藏测试集 · 初始 ${x}%`, subset: "子集", selected: "★ 最终选中",
    copy: "复制", copied: "已复制 ✓",
  } : {
    data: "Data", trainer: "Trainer", harness: "Harness",
    tcHarness: "Harness", tcVal: "Validation", tcTest: "Hidden test", tcSettings: "Evaluation settings",
    agentCol: "Research agent", avg: "Average", hours: "Hours",
    refInit: "Initial ", refInst: "Instruct ",
    tcCap: (name, who, s, d, inst, spread) => `<b>${name}.</b> Leader: <b>${who}</b> at ${s}% (+${d} over the initial system). The human-developed instruct model scores ${inst}%; the spread across research agents is ${spread} points.`,
    fiveAvg: "Five-task average",
    vtHead: ["Task", "Validation leader", "", "Hidden-test leader"],
    abInit: "Initial", abCap: "Kimi-K3 hidden-test scores (%). Kimi-K3 did not edit the harness in its SWE D/T/H run.",
    sparkTitle: "Validation result per decision", sparkHollow: " · hollow = subset validation",
    meta: (task, fw, fig) => `${task} · ${fw} · paper ${fig}`,
    hidden: (x) => `hidden test · initial ${x}%`, subset: "subset", selected: "★ selected",
    copy: "Copy", copied: "Copied ✓",
  };
  const COMP = { D: { label: I.data, cls: "d", color: "#2b7bba" }, T: { label: I.trainer, cls: "t", color: "#d9881a" }, H: { label: I.harness, cls: "h", color: "#8c5bb5" } };
  const fmt = (x, d = 1) => (x == null ? "–" : Number(x).toFixed(d));
  const chips = (cs, sm = true) => cs.map((c) => `<span class="chip ${COMP[c].cls}${sm ? " sm" : ""}">${c}</span>`).join("");

  /* ---------------- nav / progress / reveal ---------------- */
  const nav = $("#nav");
  const hero = $(".hero");
  const progress = $("#progress");
  function onScroll() {
    const y = window.scrollY;
    nav.classList.toggle("scrolled", y > 12);
    nav.classList.toggle("solid", y > hero.offsetHeight - 80);
    const h = document.documentElement.scrollHeight - window.innerHeight;
    progress.style.width = (h > 0 ? (y / h) * 100 : 0) + "%";
  }
  window.addEventListener("scroll", onScroll, { passive: true });
  onScroll();

  $("#navToggle").addEventListener("click", () => $("#navLinks").classList.toggle("open"));
  $$("#navLinks a").forEach((a) => a.addEventListener("click", () => $("#navLinks").classList.remove("open")));

  const links = $$('#navLinks a[href^="#"]');
  const secObs = new IntersectionObserver((entries) => {
    entries.forEach((en) => {
      if (!en.isIntersecting) return;
      links.forEach((l) => l.classList.toggle("active", l.getAttribute("href") === "#" + en.target.id));
    });
  }, { rootMargin: "-45% 0px -50% 0px" });
  links.forEach((l) => { const s = $(l.getAttribute("href")); if (s) secObs.observe(s); });

  const revObs = new IntersectionObserver((entries) => {
    entries.forEach((en) => {
      if (en.isIntersecting) { en.target.classList.add("in"); revObs.unobserve(en.target); }
    });
  }, { threshold: 0.12 });
  function observeReveal(root = document) { $$(".reveal:not(.in)", root).forEach((el) => revObs.observe(el)); }

  // count-up for headline number
  function countUp(el) {
    const target = parseFloat(el.dataset.count), dec = parseInt(el.dataset.decimals || "0", 10);
    const t0 = performance.now(), dur = 1400, from = parseFloat(el.dataset.from || "0");
    function step(t) {
      const p = Math.min(1, (t - t0) / dur), e = 1 - Math.pow(1 - p, 3);
      el.textContent = (from + (target - from) * e).toFixed(dec);
      if (p < 1) requestAnimationFrame(step);
    }
    requestAnimationFrame(step);
  }
  const hlObs = new IntersectionObserver((entries) => {
    entries.forEach((en) => {
      if (!en.isIntersecting) return;
      countUp($(".hl-big .to", en.target));
      hlObs.unobserve(en.target);
    });
  }, { threshold: 0.4 });
  $$(".headline-card").forEach((card) => hlObs.observe(card));

  /* ---------------- protocol table (Table 1) ---------------- */
  (function renderProtocol() {
    const GL = { Y: ["y", "✓"], P: ["p", "△"], N: ["n", "✗"], "-": ["na", "–"] };
    const groups = [];
    V.PROTOCOL_COLS.forEach((c) => {
      const last = groups[groups.length - 1];
      if (last && last.name === c.group) last.span++; else groups.push({ name: c.group, span: 1 });
    });
    let html = `<thead><tr class="grp"><th></th>${groups.map((g) => `<th colspan="${g.span}"><span>${g.name}</span></th>`).join("")}</tr>`;
    html += `<tr><th>Benchmark</th>${V.PROTOCOL_COLS.map((c) => `<th>${c.label}</th>`).join("")}</tr></thead><tbody>`;
    V.PROTOCOL.forEach((r) => {
      html += `<tr class="${r.ours ? "ours" : ""}"><td>${r.name}</td>${r.v.split("").map((k) => `<td><span class="g ${GL[k][0]}">${GL[k][1]}</span></td>`).join("")}</tr>`;
    });
    $("#protocolTable").innerHTML = html + "</tbody>";
  })();

  /* ---------------- task cards (Table 2 + 6) ---------------- */
  const ICONS = {
    terminal: '<svg viewBox="0 0 24 24"><rect x="3" y="4" width="18" height="16" rx="2"/><path d="M7 9l3 3-3 3M13 15h4"/></svg>',
    code: '<svg viewBox="0 0 24 24"><path d="M8 7l-5 5 5 5M16 7l5 5-5 5M14 4l-4 16"/></svg>',
    chat: '<svg viewBox="0 0 24 24"><path d="M21 12a8 8 0 0 1-11.6 7.1L4 20l1-4.6A8 8 0 1 1 21 12z"/><path d="M8.5 12h.01M12 12h.01M15.5 12h.01"/></svg>',
    tool: '<svg viewBox="0 0 24 24"><path d="M14.7 6.3a4 4 0 0 0 5 5L21 13l-8 8-3-3 8-8-1.3-1.3a4 4 0 0 0-5-5L13 5z"/><path d="M3 21l6-6"/></svg>',
    math: '<svg viewBox="0 0 24 24"><path d="M4 6h7M7.5 2.5v7M14 5l5 5M19 5l-5 5M4 17h7M14 15h6M14 19h6"/></svg>',
  };
  $("#taskCards").innerHTML = V.TASKS.map((t) => `
    <article class="task reveal">
      <span class="budget">${t.budget}</span>
      <div class="t-ic">${ICONS[t.icon]}</div>
      <p class="cap">${t.capability}</p>
      <h4>${t.name}</h4>
      <div class="edit">${["D", "T", "H"].map((c) => `<span class="chip ${COMP[c].cls} sm${t.editable.includes(c) ? "" : " off"}">${c}</span>`).join("")}</div>
      <dl>
        <dt>${I.tcHarness}</dt><dd>${t.harness}</dd>
        <dt>${I.tcVal}</dt><dd>${t.validation}</dd>
        <dt>${I.tcTest}</dt><dd>${t.test}</dd>
      </dl>
      <details><summary>${I.tcSettings}</summary><p>${t.settings}</p></details>
    </article>`).join("");

  /* ---------------- leaderboard (Table 3) ---------------- */
  const INIT = V.REFERENCE[0], INST = V.REFERENCE[1];
  const COLS = [{ id: "avg", label: I.avg }, ...V.TASK_COLS.map((c) => ({ id: c.id, label: c.label })), { id: "hours", label: I.hours }];
  const scoreCols = COLS.filter((c) => c.id !== "hours").map((c) => c.id);
  let lbMode = "abs", sortKey = "avg", sortDir = -1;

  function val(row, col) {
    const x = row[col];
    if (col === "hours" || x == null) return x;
    if (lbMode === "delta") return x - INIT[col];
    if (lbMode === "gap") return ((x - INIT[col]) / (INST[col] - INIT[col])) * 100;
    return x;
  }
  function cellText(row, col, isRef) {
    const x = val(row, col);
    if (x == null) return "–";
    if (col === "hours") return fmt(x);
    if (lbMode === "abs") return fmt(x);
    if (isRef && row.id === "initial") return "–";
    const s = lbMode === "gap" ? fmt(x, 0) + "%" : (x > 0 ? "+" : "") + fmt(x);
    return s;
  }
  function renderLB() {
    const rows = V.RESULTS.slice().sort((a, b) => sortDir * ((val(a, sortKey) ?? -1e9) - (val(b, sortKey) ?? -1e9)));
    const stats = {};
    scoreCols.forEach((c) => {
      const vs = V.RESULTS.map((r) => val(r, c));
      stats[c] = { min: Math.min(...vs), max: Math.max(...vs) };
    });
    let html = `<thead><tr><th data-k="name">${I.agentCol}</th>${COLS.map((c) => `<th data-k="${c.id}" class="${sortKey === c.id ? "sorted" : ""}" data-dir="${sortDir < 0 ? "↓" : "↑"}">${c.label}</th>`).join("")}</tr></thead><tbody>`;
    V.REFERENCE.forEach((r, i) => {
      html += `<tr class="ref${i === V.REFERENCE.length - 1 ? " ref-last" : ""}"><td><div class="agent"><span class="rank"></span><span class="dot" style="background:${i ? "#2a2f3a" : "#9aa3b8"}"></span><div><b>${r.name}</b><small>${r.note}</small></div></div></td>`;
      html += COLS.map((c) => `<td class="cell ${c.id === "avg" ? "avg" : ""}"><span class="v">${cellText(r, c.id, true)}</span></td>`).join("") + "</tr>";
    });
    rows.forEach((r, i) => {
      const a = AG[r.agent];
      html += `<tr><td><div class="agent"><span class="rank">${sortKey === "hours" ? "" : i + 1}</span><span class="dot" style="background:${a.color}"></span><div><b>${a.name}</b><small>${a.framework}</small></div></div></td>`;
      html += COLS.map((c) => {
        if (c.id === "hours") return `<td class="cell"><span class="v">${fmt(r.hours)}</span></td>`;
        const x = val(r, c.id), st = stats[c.id];
        const k = st.max > st.min ? (x - st.min) / (st.max - st.min) : 1;
        const best = x === st.max;
        const cls = lbMode === "abs" ? "" : x > 0.0001 ? "pos" : x < -0.0001 ? "neg" : "zero";
        return `<td class="cell ${c.id === "avg" ? "avg" : ""} ${best ? "best" : ""}"><span class="heat" style="background:rgba(91,75,214,${(0.04 + 0.2 * k).toFixed(3)})"></span><span class="v ${cls}">${cellText(r, c.id)}</span></td>`;
      }).join("") + "</tr>";
    });
    $("#lbTable").innerHTML = html + "</tbody>";
    $$("#lbTable thead th[data-k]").forEach((th) => {
      const k = th.dataset.k;
      if (k === "name") return;
      th.addEventListener("click", () => {
        if (sortKey === k) sortDir *= -1; else { sortKey = k; sortDir = k === "hours" ? 1 : -1; }
        renderLB();
      });
    });
  }
  $$("#lbMode button").forEach((b) => b.addEventListener("click", () => {
    $$("#lbMode button").forEach((x) => x.classList.toggle("on", x === b));
    lbMode = b.dataset.mode; renderLB();
  }));
  renderLB();

  /* ---------------- per-task bar chart ---------------- */
  const tcOpts = [{ id: "avg", label: I.avg }, ...V.TASK_COLS.map((c) => ({ id: c.id, label: c.short }))];
  let tcKey = "avg";
  $("#tcSel").innerHTML = tcOpts.map((o) => `<button data-k="${o.id}" class="${o.id === tcKey ? "on" : ""}">${o.label}</button>`).join("");
  $$("#tcSel button").forEach((b) => b.addEventListener("click", () => {
    $$("#tcSel button").forEach((x) => x.classList.toggle("on", x === b));
    tcKey = b.dataset.k; renderTaskChart();
  }));
  function renderTaskChart() {
    const k = tcKey;
    const rows = V.RESULTS.slice().sort((a, b) => b[k] - a[k]);
    const max = Math.max(INST[k], ...rows.map((r) => r[k])) * 1.12;
    const pct = (x) => (x / max) * 100;
    const el = $("#taskChart");
    if (!el.dataset.built) {
      el.innerHTML = rows.map(() => `<div class="bar-row"><div class="bl"></div><div class="bt"><div class="bf"><span></span></div></div></div>`).join("") +
        `<div class="bars-overlay"><div class="refline init"><span></span></div><div class="refline inst"><span></span></div></div>`;
      el.dataset.built = "1";
    }
    $$(".bar-row", el).forEach((row, i) => {
      const r = rows[i], a = AG[r.agent];
      $(".bl", row).innerHTML = `<span class="dot" style="width:9px;height:9px;border-radius:50%;background:${a.color}"></span>${a.name}`;
      const bf = $(".bf", row);
      bf.style.width = pct(r[k]) + "%";
      bf.style.background = a.color;
      bf.classList.toggle("short", pct(r[k]) < 12);
      $("span", bf).textContent = fmt(r[k]);
    });
    const ov = $(".bars-overlay", el);
    $(".refline.init", ov).style.left = pct(INIT[k]) + "%";
    $(".refline.init span", ov).textContent = I.refInit + fmt(INIT[k]);
    $(".refline.inst", ov).style.left = pct(INST[k]) + "%";
    $(".refline.inst span", ov).textContent = I.refInst + fmt(INST[k]);
    const best = rows[0];
    const ties = rows.filter((r) => r[k] === best[k]).map((r) => AG[r.agent].name).join(" & ");
    const name = k === "avg" ? I.fiveAvg : V.TASK_COLS.find((c) => c.id === k).label;
    $("#tcCaption").innerHTML = I.tcCap(name, ties, fmt(best[k]), fmt(best[k] - INIT[k]), fmt(INST[k]), fmt(best[k] - rows[rows.length - 1][k]));
  }
  renderTaskChart();

  /* ---------------- validation vs test ---------------- */
  $("#valTest").innerHTML = `<div class="vt-head">${I.vtHead.map((h) => `<span>${h}</span>`).join("")}</div>` +
    V.VAL_VS_TEST.map((r) => `<div class="vt-row ${r.transfer ? "ok" : "no"}"><span class="tk">${r.task}</span><span>${r.val}</span><span class="ic">${r.transfer ? "=" : "≠"}</span><span><b>${r.test}</b> · ${fmt(r.testScore)}%</span></div>`).join("");

  /* ---------------- ablation (Table 4) ---------------- */
  (function renderAblation() {
    const fills = {
      "Initial system": "#9aa3b8",
      "H only": "var(--h)",
      "D/T only": "linear-gradient(90deg, var(--d), var(--t))",
      "D/T/H": "linear-gradient(90deg, var(--d), var(--t), var(--h))",
    };
    const tags = { "Initial system": [], "H only": ["H"], "D/T only": ["D", "T"], "D/T/H": ["D", "T", "H"] };
    const group = (key, title, max) => `<div class="ab-group"><h5>${title}</h5>` + V.ABLATION.map((r) => {
      const x = r[key];
      return `<div class="ab-row"><span class="ab-tags">${tags[r.setting].length ? chips(tags[r.setting]) : `<span class="muted small">${I.abInit}</span>`}</span>` +
        `<div class="ab-track"><div class="ab-fill" data-w="${x == null ? 0 : (x / max) * 100}" style="background:${fills[r.setting]}"></div></div>` +
        `<span class="ab-v">${x == null ? "–" : fmt(x)}</span></div>`;
    }).join("") + "</div>";
    const el = $("#ablationChart");
    el.innerHTML = group("swe", "SWE-bench Verified", 60) + group("terminal", "Terminal-Bench 2.1", 30) +
      `<p class="caption">${I.abCap}</p>`;
    const o = new IntersectionObserver((en) => {
      if (en[0].isIntersecting) { $$(".ab-fill", el).forEach((f) => (f.style.width = f.dataset.w + "%")); o.disconnect(); }
    }, { threshold: 0.3 });
    o.observe(el);
  })();

  /* ---------------- trajectory explorer ---------------- */
  (function renderTrajectories() {
    const byTask = {};
    V.TRAJECTORIES.forEach((t) => (byTask[t.task] = byTask[t.task] || []).push(t));
    $("#txList").innerHTML = Object.entries(byTask).map(([task, list]) =>
      `<div class="tx-group">${task}</div>` + list.map((t) => {
        const a = AG[t.agent];
        return `<button class="tx-item" data-id="${t.id}"><span class="dot" style="background:${a.color}"></span>${a.name}<span class="sc">${fmt(t.hidden)}%</span></button>`;
      }).join("")).join("");

    function spark(t) {
      const pts = t.steps.filter((s) => !s.gap);
      if (pts.length < 2) return "";
      const W = 640, H = 120, pl = 30, pr = 16, pt = 16, pb = 22;
      const ys = pts.map((s) => (s.v[0] / s.v[1]) * 100);
      const ymax = Math.max(10, Math.ceil((Math.max(...ys) * 1.2) / 10) * 10);
      const X = (i) => pl + (i * (W - pl - pr)) / (pts.length - 1);
      const Y = (v) => pt + (H - pt - pb) * (1 - v / ymax);
      const color = AG[t.agent].color;
      let s = `<svg viewBox="0 0 ${W} ${H}">`;
      [0, ymax / 2, ymax].forEach((g) => {
        s += `<line x1="${pl}" x2="${W - pr}" y1="${Y(g)}" y2="${Y(g)}" stroke="#ece8df"/><text x="${pl - 6}" y="${Y(g) + 3.5}" font-size="10" text-anchor="end" fill="#8a909c">${Math.round(g)}%</text>`;
      });
      s += `<polyline fill="none" stroke="${color}" stroke-width="2.2" stroke-linejoin="round" points="${ys.map((v, i) => `${X(i)},${Y(v)}`).join(" ")}"/>`;
      pts.forEach((p, i) => {
        const x = X(i), y = Y(ys[i]);
        if (p.sel) s += `<path d="M${x} ${y - 11} l3.1 6.4 7 .9-5.1 4.9 1.3 7-6.3-3.4-6.3 3.4 1.3-7-5.1-4.9 7-.9z" fill="#f5c542" stroke="#8a6400" stroke-width="1"/>`;
        else s += `<circle cx="${x}" cy="${y}" r="4.5" fill="${p.sub ? "#fff" : color}" stroke="${color}" stroke-width="2"/>`;
        s += `<text x="${x}" y="${H - 6}" font-size="10" text-anchor="middle" fill="#646b78">D${p.n}</text>`;
        s += `<text x="${x}" y="${y - (p.sel ? 15 : 9)}" font-size="10" text-anchor="middle" fill="#2d3139" font-weight="600">${p.v[0]}/${p.v[1]}</text>`;
      });
      return `<div class="spark"><h6>${I.sparkTitle}${pts.some((p) => p.sub) ? I.sparkHollow : ""}</h6>${s}</svg></div>`;
    }

    function show(id) {
      const t = V.TRAJECTORIES.find((x) => x.id === id);
      const a = AG[t.agent];
      $$(".tx-item").forEach((b) => b.classList.toggle("on", b.dataset.id === id));
      const init = INIT[V.TASK_COLS.find((c) => c.label === t.task).id];
      $("#txMain").innerHTML = `
        <div class="tx-top">
          <div>
            <h3><span class="dot" style="width:12px;height:12px;border-radius:50%;background:${a.color};display:inline-block"></span>${a.name}</h3>
            <p class="meta">${I.meta(t.task, a.framework, t.fig)}</p>
          </div>
          <div class="tx-score"><b style="color:${a.color}">${fmt(t.hidden)}%</b><span>${I.hidden(fmt(init))}</span></div>
        </div>
        <p class="tx-summary">${t.summary}</p>
        ${spark(t)}
        <ol class="tl">${t.steps.map((s, i) => s.gap
          ? `<li class="gap" style="animation-delay:${i * 40}ms"><span class="pin">…</span>· · ·</li>`
          : `<li class="${s.sel ? "sel" : ""}" style="animation-delay:${i * 40}ms"><span class="pin">${s.n}</span>
              <div class="step-card"><div class="sh"><h5>${chips(s.c)} ${s.title}</h5>
              <span class="res">${s.v[0]}/${s.v[1]}${s.sub ? `<i>${I.subset}</i>` : ""}${s.sel ? `<span class="star">${I.selected}</span>` : ""}</span></div>
              <p>${s.text}</p></div></li>`).join("")}
        </ol>`;
    }
    $$(".tx-item").forEach((b) => b.addEventListener("click", () => show(b.dataset.id)));
    show(V.TRAJECTORIES[0].id);
  })();

  /* ---------------- citation copy ---------------- */
  $("#copyBib").addEventListener("click", () => {
    const text = $("#bibtex").innerText;
    const done = () => { $("#copyBib").textContent = I.copied; setTimeout(() => ($("#copyBib").textContent = I.copy), 1600); };
    if (navigator.clipboard) navigator.clipboard.writeText(text).then(done, done);
    else { const ta = document.createElement("textarea"); ta.value = text; document.body.appendChild(ta); ta.select(); document.execCommand("copy"); ta.remove(); done(); }
  });

  /* ---------------- lightbox ---------------- */
  const lb = $("#lightbox");
  document.addEventListener("click", (e) => {
    const img = e.target.closest("img[data-zoom]");
    if (img) { $("img", lb).src = img.src; lb.classList.add("open"); lb.setAttribute("aria-hidden", "false"); }
  });
  lb.addEventListener("click", () => { lb.classList.remove("open"); lb.setAttribute("aria-hidden", "true"); });
  document.addEventListener("keydown", (e) => { if (e.key === "Escape") lb.click(); });

  $$('a[aria-disabled="true"]').forEach((a) => a.addEventListener("click", (e) => e.preventDefault()));

  /* ---------------- language switch: keep the reader on the same section ---------------- */
  $$("[data-lang-switch]").forEach((a) => a.addEventListener("click", () => {
    const active = $("#navLinks a.active");
    const hash = window.scrollY < hero.offsetHeight - 80 ? "" : (active ? active.getAttribute("href") : location.hash);
    a.href = a.getAttribute("href").split("#")[0] + hash;
  }));

  observeReveal();
})();
